"""Run two frozen native last-block diagnostics sequentially with verified core bytes."""
import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import zlib

PAYLOAD_B64 = ''
MAX_EXEC_BYTES = 96 * 1024
MAX_FILES = 128
MAX_OUTPUT_BYTES = 64 * 1024 * 1024
DRIVER_NAME = 'native_jax_bf16_splash_15b_separate_capture'
CHILD = r'''import hashlib,importlib,json,os,pathlib,sys
sys.path.insert(0,"/tmp")
driver=importlib.import_module("native_jax_bf16_splash_15b_separate_capture")
core=importlib.import_module("levanter.grug.attention._core")
levanter=importlib.import_module("levanter")
haliax=importlib.import_module("haliax")
root=pathlib.Path(os.environ["AB_EXPECTED_WORKTREE"]).resolve()
actual_core=pathlib.Path(core.__file__).resolve()
if actual_core!=root/"lib/levanter/src/levanter/grug/attention/_core.py":raise ValueError("Imported core from wrong source tree")
core_sha=hashlib.sha256(actual_core.read_bytes()).hexdigest()
if core_sha!=os.environ["AB_EXPECTED_CORE_SHA"]:raise ValueError("Imported core file bytes differ")
barrier_present="optimization_barrier" in core._tpu_splash_attention.__code__.co_names
if barrier_present!=(os.environ["AB_VARIANT"]=="candidate"):raise ValueError("Actual imported Python function does not match barrier variant")
modules={"core":str(actual_core),"levanter":levanter.__file__,"haliax":haliax.__file__,"benchmark":driver.prior.bench.__file__}
for name in ["levanter","haliax","benchmark"]:
 if not pathlib.Path(modules[name]).resolve().is_relative_to(root):raise ValueError("Imported module from wrong source tree: "+name)
record_path=pathlib.Path(os.environ["AB_LAUNCH_RECORD"])
record=json.loads(record_path.read_text())
record["runtime_child_imports"]={"modules":modules,"core_sha256":core_sha,"actual_function_contains_barrier":barrier_present,"dont_write_bytecode":sys.dont_write_bytecode,"pycache_prefix":sys.pycache_prefix}
record_path.write_text(json.dumps(record,indent=2,sort_keys=True)+"\n")
driver.SOURCE=os.environ["SOURCE_COMMIT"]
driver.CAPTURE_HLO_TOTAL_LIMIT=12*1024*1024
driver.prior.HLO_TOTAL_LIMIT=16*1024*1024
sys.argv=[driver.__file__,*sys.argv[1:]]
driver.main()
'''


def digest(data):
    return hashlib.sha256(data).hexdigest()


def write_json(path, data):
    path.write_text(json.dumps(data, indent=2, sort_keys=True) + '\n')


def source_files(worktree, expected):
    actual = {name: digest((worktree / name).read_bytes()) for name in expected}
    if actual != expected:
        raise ValueError('Actual source bytes differ from the exact child variant')
    return actual


def verify_assets(payload):
    installed = {}
    for name, text in payload['assets'].items():
        path = Path('/tmp') / name
        data = text.encode()
        if digest(data) != payload['asset_sha256'][name]:
            raise ValueError('Embedded frozen asset hash mismatch')
        # Retain the same /tmp filenames as the proven separate-capture run.
        if path.exists() and path.read_bytes() != data:
            raise FileExistsError(f'Existing frozen asset differs: {path}')
        if not path.exists():
            path.write_bytes(data)
        installed[name] = {'path': str(path), 'sha256': digest(path.read_bytes()), 'bytes': len(data)}
    return installed


def command_environment_bytes(command, env):
    return {'argument_bytes': sum(len(value.encode()) + 1 for value in command),
        'environment_bytes': sum(len((key + '=' + value).encode()) + 1 for key, value in env.items()),
        'largest_argument_bytes': max(len(value.encode()) for value in command)}


def child_run(label, payload, worktree, output, small, abstract, backend):
    pin = payload['base_source'] if label == 'baseline' else payload['candidate_source']
    expected = payload['baseline_file_sha256'] if label == 'baseline' else payload['candidate_file_sha256']
    actual = source_files(worktree, expected)
    env = dict(os.environ)
    env['SOURCE_COMMIT'] = pin
    env['PYTHONDONTWRITEBYTECODE'] = '1'
    env['PYTHONPYCACHEPREFIX'] = f'/tmp/native-jax-q-ab-empty-pycache-{os.getpid()}-{label}'
    env['AB_EXPECTED_WORKTREE'] = str(worktree)
    env['AB_EXPECTED_CORE_SHA'] = expected[payload['core_path']]
    env['AB_VARIANT'] = label
    env['AB_LAUNCH_RECORD'] = str(output / f'{label}-launch.json')
    env['PYTHONPATH'] = str(worktree / 'lib/levanter/src') + ':' + str(worktree / 'lib/haliax/src')
    command = [sys.executable, '-c', CHILD, '--expected-backend', backend, '--output-dir', str(output / label)]
    if small:
        command.append('--small')
    if abstract:
        command.append('--abstract-only')
    sizes = command_environment_bytes(command, env)
    if sizes['argument_bytes'] + sizes['environment_bytes'] >= MAX_EXEC_BYTES:
        raise ValueError('Child exec arguments plus environment exceed96KiB')
    before = {'effective_source_pin': pin, 'actual_source_file_sha256_before_import': actual,
        'child_command': command, 'exec_sizes': sizes,
        'environment_scope': {key: env.get(key) for key in ['SOURCE_COMMIT', 'PYTHONDONTWRITEBYTECODE', 'PYTHONPATH', 'JAX_PLATFORMS', 'JAX_NUM_CPU_DEVICES', 'XLA_FLAGS']},
        'frozen_driver_overrides': {'SOURCE': pin, 'CAPTURE_HLO_TOTAL_LIMIT': 12 * 1024 * 1024, 'prior.HLO_TOTAL_LIMIT': 16 * 1024 * 1024},
        'parent_imported_jax': 'jax' in sys.modules}
    write_json(output / f'{label}-launch.json', before)
    result = subprocess.run(command, cwd=worktree, env=env)
    before = json.loads((output / f'{label}-launch.json').read_text())
    before['exit_code'] = result.returncode
    before['actual_source_file_sha256_after_exit'] = source_files(worktree, expected)
    write_json(output / f'{label}-launch.json', before)
    return before


def inspect_child(label, payload, output, small, abstract):
    directory = output / label
    required = ['abstract-shapes.json'] if abstract else ['provenance.json', 'controls.json', 'case-outcomes.json', *(f'last-{stage}.json' for stage in ['full', 'prefix', 'tail', 'composed'])]
    missing = [name for name in required if not (directory / name).is_file()]
    if missing:
        return {'passed': False, 'missing_required_reports': missing, 'reason': 'Child failed before completing required controls; retained available evidence must be inspected.'}
    if abstract:
        data = json.loads((directory / 'abstract-shapes.json').read_text())
        return {'passed': data['parameter_count'] == 1531037696 and data['named_attention_backend'] == 'splash' and data['native_attention_implementation'] == 'tpu_splash' and data['no_model_parameters_allocated'], 'abstract': data}
    provenance = json.loads((directory / 'provenance.json').read_text())
    controls = json.loads((directory / 'controls.json').read_text())
    outcome = json.loads((directory / 'case-outcomes.json').read_text())
    stages = {stage: json.loads((directory / f'last-{stage}.json').read_text()) for stage in ['full', 'prefix', 'tail', 'composed']}
    guards = {'all_source_forward_loss_guards_exact': provenance['capture_controls_exact'],
        'all5_source_operand_hash_guards_exact': provenance['source_operand_hashes_exact'],
        'source_replay_boundaries_exact': controls['source_replay_boundaries_exact'],
        'all33_full_composed_values_exact': all(controls['single_jit_full_vs_composed_exact'].values()),
        'all_common_argument_hash_dtypes_physical_specs_exact': all(data['common_bf16_operands_fp32_masters_and_physical_specs_exact'] for data in stages.values()),
        'all_outputs_finite': outcome['all_values_finite'], 'completed': outcome['completed'], 'replay_attribution_valid': outcome['attribution_valid']}
    current = {}
    for stage in ['full', 'prefix']:
        data = stages[stage];order = data['named']['result_order']
        current[stage] = {variant: {name: data[variant]['results'][order.index(name)]['sha256'] for name in ['forward', 'input_vjp', 'self_attn.q_proj.weight']} for variant in ['named', 'native']}
    if label == 'baseline' and not small:
        guards['prior_full_prefix_forward_dx_q_hashes_exact'] = current == payload['prior_baseline_result_hashes']
    if not small:
        guards['all5_source_hashes_match_reviewed_original'] = {name: record['sha256'] for name, record in provenance['source_operands'].items()} == payload['source_operand_hashes']
    return {'passed': all(guards.values()), 'guards': guards, 'prior_large_result_hash_check_applicable': not small,
        'actual_full_prefix_result_hashes': current, 'stages': stages, 'source_provenance': provenance, 'controls': controls}


def compare_children(baseline, candidate):
    guards = {}
    changes = {}
    for stage in ['full', 'prefix', 'tail', 'composed']:
        left, right = baseline['stages'][stage], candidate['stages'][stage]
        order = left['named']['result_order']
        guards[f'{stage}_named_all11_result_hashes_unchanged'] = [v['sha256'] for v in left['named']['results']] == [v['sha256'] for v in right['named']['results']]
        for variant in ['named', 'native', 'fp32']:
            guards[f'{stage}_{variant}_forward_hash_unchanged'] = left[variant]['results'][0]['sha256'] == right[variant]['results'][0]['sha256']
        changes[stage] = {}
        before_rows, after_rows = left['comparisons']['named_vs_native'], right['comparisons']['named_vs_native']
        for i, name in enumerate(order):
            changes[stage][name] = {'before_named_vs_native': before_rows[i], 'after_named_vs_native': after_rows[i],
                'native_result_hash_changed': left['native']['results'][i]['sha256'] != right['native']['results'][i]['sha256'],
                'mismatch_removed': not before_rows[i]['exact'] and after_rows[i]['exact'],
                'mismatch_introduced': before_rows[i]['exact'] and not after_rows[i]['exact']}
    return {'guards': guards, 'all_named_results_and_all_forward_hashes_unchanged': all(guards.values()),
        'per_output_changes': changes,
        'interpretation': 'Barrier A/B plus saved HLO only. Common raw-dQ control deferred. Candidate native gradients are compared, not required equal baseline. Passing controls do not establish fullTrainer backward identity, accepted trajectory, performance or convergence.'}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--worktree', type=Path, required=True)
    parser.add_argument('--output-dir', type=Path, required=True)
    parser.add_argument('--expected-backend', choices=['cpu', 'tpu'], required=True)
    parser.add_argument('--small', action='store_true')
    parser.add_argument('--abstract-only', action='store_true')
    args = parser.parse_args()
    if args.small and args.abstract_only:
        raise ValueError('Choose small CPU proof or actual large abstract proof')
    if os.environ.get('XLA_FLAGS') != '--xla_allow_excess_precision=false':
        raise ValueError('Exact XLA flags required')
    if 'jax' in sys.modules:
        raise RuntimeError('Parent must not initialize/import JAX')
    payload = json.loads(zlib.decompress(base64.b64decode(PAYLOAD_B64)))
    worktree = args.worktree.resolve()
    output = args.output_dir.resolve()
    output.mkdir(parents=True, exist_ok=True)
    if any(output.iterdir()):
        raise FileExistsError('Use fresh empty diagnostic output directory')
    core = worktree / payload['core_path']
    candidate_bytes = payload['candidate_core'].encode()
    baseline_bytes = payload['baseline_core'].encode()
    # Baseline byte substitution occurs only in this explicitly supplied disposable source tree.
    source_files(worktree, payload['candidate_file_sha256'])
    if core.read_bytes() != candidate_bytes:
        raise ValueError('Initial source must contain exact reviewed candidate core bytes')
    installed = verify_assets(payload)
    launches = {}
    try:
        core.write_bytes(baseline_bytes)
        launches['baseline'] = child_run('baseline', payload, worktree, output, args.small, args.abstract_only, args.expected_backend)
    finally:
        core.write_bytes(candidate_bytes)
    launches['candidate'] = child_run('candidate', payload, worktree, output, args.small, args.abstract_only, args.expected_backend)
    restored = source_files(worktree, payload['candidate_file_sha256'])
    inspected = {label: inspect_child(label, payload, output, args.small, args.abstract_only) for label in ['baseline', 'candidate']}
    comparable = not args.abstract_only and all('stages' in value for value in inspected.values())
    comparison = compare_children(inspected['baseline'], inspected['candidate']) if comparable else None
    passed = all(v['exit_code'] == 0 for v in launches.values()) and all(v['passed'] for v in inspected.values())
    if comparison is not None:
        passed = passed and comparison['all_named_results_and_all_forward_hashes_unchanged']
    summary = {'schema': 'native-query-scale-barrier-ab-v1', 'passed_controls': passed,
        'baseline_source': payload['base_source'], 'candidate_source': payload['candidate_source'],
        'driver_sha256': digest(Path(__file__).read_bytes()), 'frozen_assets': installed,
        'actual_final_candidate_file_sha256': restored, 'actual_core_substitution': {'baseline_sha256': digest(baseline_bytes), 'candidate_sha256': digest(candidate_bytes), 'candidate_restored': core.read_bytes() == candidate_bytes},
        'parent_imported_jax': 'jax' in sys.modules, 'children_sequential': True, 'small_cpu_proof': args.small,
        'actual_large_abstract_only': args.abstract_only, 'small_cpu_limitation': 'CPU vanilla/reference harness only; BF16 Splash candidate path is not executed.' if args.small else None,
        'launches': launches, 'child_controls': {label: {key: value for key, value in v.items() if key not in ['stages', 'source_provenance', 'controls']} for label, v in inspected.items()},
        'comparison': comparison, 'raw_dq_control_performed': False, 'full_trainer_identity_tested': False,
        'limits': {'source_hlo_bytes_per_child': 12 * 1024 * 1024, 'vjp_hlo_bytes_per_child': 16 * 1024 * 1024,
            'combined_hlo_bytes': 56 * 1024 * 1024, 'archive_entries': MAX_FILES, 'archive_uncompressed_bytes': MAX_OUTPUT_BYTES}}
    write_json(output / 'ab-summary.json', summary)
    files = [p for p in output.rglob('*') if p.is_file()]
    count, total = len(files), sum(p.stat().st_size for p in files)
    if count + 1 > MAX_FILES or total + 1024 * 1024 > MAX_OUTPUT_BYTES:
        raise ValueError('Aggregate output exceeds bounded archive budget')
    write_json(output / 'ab-files.json', {'files_before_manifest': count, 'bytes_before_manifest': total,
        'files_with_manifest': count + 1, 'entries': [{'path':str(p.relative_to(output)), 'bytes':p.stat().st_size,'sha256':digest(p.read_bytes())} for p in sorted(files)]})
    print('QUERY_SCALE_AB_DONE ' + json.dumps({'passed_controls': passed, 'files': count + 1, 'bytes_before_manifest': total, 'parent_jax_imported': 'jax' in sys.modules}), flush=True)
    if not passed:
        raise ValueError('A/B source/reference controls failed; preserve evidence, no attribution')


if __name__ == '__main__':
    main()
